/**
 * worker.ts — api.careers, wave zero: both plies from the one definition.
 *
 *   data face      GET  /placements /candidates /job-orders /occupations (+/{id})
 *   headless face  POST /placements /candidates /job-orders  — the ATS
 *                  system-of-record doors on the SAME collections, same
 *                  envelopes, same rate-card rows (there is no second API)
 *   quartet        generated by the vendored axp-faces generator from ONE
 *                  defineSiteManifest() (./manifest.ts) — never hand-rolled
 *   MCP            POST /mcp — JSON-RPC tools/list + tools/call over the SAME
 *                  operation registry the REST doors use (one definition)
 *
 * Anon sandbox is the universal floor: every door above answers keyless.
 * POST doors auto-mint an ephemeral workspace (disclosed retention). Seams
 * (metering / money events / signup-traffic) are emitted as structured
 * events, tagged per spec §6.4 — seams only, no billing, no account UI.
 */

// @ts-ignore — vendored byte-identical JS (PINS.json digest-checked); never edited here
import { createAxpRoutes, envelopeResponse, ok, empty, blocked, collectionDecision } from './axp/index.js'
import { manifest, ORIGIN } from './manifest.ts'
import { staffingTalent, type OperationDef } from './substrate.ts'
import { apiCareersProjection } from './projection.ts'
