// ─── seams (§7.4: emitted, never rendered as account UI) ────────────────────

export interface SeamEvent {
  seam: 'meter' | 'money-event' | 'receipt' | 'signup' | 'traffic'
  substrate: string
  projection: string
  motion: string
  operation?: string
  shape: string
  pattern: string
  identityClass?: string
  referral?: string
  stub?: boolean
  ts: string
  [k: string]: unknown
}

/** In-memory seam buffer — the wave-zero seam surface; a queue/analytics
 *  binding replaces the sink at extraction, the tags do not change. */
export const seams: SeamEvent[] = []

function emitSeam(event: Omit<SeamEvent, 'substrate' | 'projection' | 'motion' | 'pattern' | 'ts' | 'shape'> & { shape?: string }): void {
  const full: SeamEvent = {
    substrate: staffingTalent.substrate,
    projection: apiCareersProjection.brand,
    motion: apiCareersProjection.motion,
    pattern: apiCareersProjection.experiment.pattern,
    shape: 'anon-sandbox',
    ts: new Date().toISOString(),
    ...event,
  }
  seams.push(full)
  if (seams.length > 1000) seams.shift()
  console.log(JSON.stringify(full))
}

function identityClassOf(request: Request): { identityClass: string; referral: string } {
  const dest = request.headers.get('sec-fetch-dest')
  const identityClass = dest === 'document' ? 'human-browser' : 'machine-anonymous' // id.org.ai grain not wired at wave zero
  const referral = request.headers.get('referer') || 'direct'
  return { identityClass, referral }
}

// ─── ephemeral sandbox workspaces (auto-mint, disclosed retention) ──────────

interface Workspace {
  id: string
  mintedAt: string
  candidates: Record<string, unknown>[]
  jobOrders: Record<string, unknown>[]
  placements: Record<string, unknown>[]
}

const workspaces = new Map<string, Workspace>()

function workspaceOf(request: Request, mint: boolean): { ws: Workspace | undefined; minted: boolean } {
  const header = request.headers.get('x-workspace')
  if (header && workspaces.has(header)) return { ws: workspaces.get(header), minted: false }
  if (!mint) return { ws: undefined, minted: false }
  const id = `ws_${crypto.randomUUID().slice(0, 12)}`
  const ws: Workspace = { id, mintedAt: new Date().toISOString(), candidates: [], jobOrders: [], placements: [] }
  workspaces.set(id, ws)
  return { ws, minted: true }
}

// ─── the operation registry: one definition, REST + MCP dispatch ────────────

type OperationArgs = { id?: string; filters?: Record<string, string>; body?: Record<string, unknown>; request: Request }
type OperationResult = { status: number; body: Record<string, unknown> }

const NOT_FOUND = (what: string, id: string): OperationResult => ({
  status: 404,
  body: { type: 'EMPTY', results: [], message: `no ${what} with id ${id} — nothing was deleted; that id was never minted here` },
})

function listOf(seed: Record<string, unknown>[], wsRecords: Record<string, unknown>[] | undefined, filters: Record<string, string> | undefined, memberName: string): OperationResult {
  let recs = [...seed, ...(wsRecords || [])]
  let filtered: [string, string] | null = null
  for (const [param, value] of Object.entries(filters || {})) {
    if (param === 'status') { recs = recs.filter((r) => String(r.status) === value); filtered = [param, value] }
    if (param === 'occupation') { recs = recs.filter((r) => String(r.onetCode) === value); filtered = [param, value] }
  }
  if (recs.length === 0) {
    const [param, value] = filtered || ['status', '']
    return { status: 200, body: empty(`no records match ${param}=${value} — a truthful empty set, not an error`, { memberName }) }
  }
  return { status: 200, body: ok(recs, { memberName }) }
}

function getOf(seed: Record<string, unknown>[], wsRecords: Record<string, unknown>[] | undefined, id: string, what: string): OperationResult {
  const rec = [...seed, ...(wsRecords || [])].find((r) => String(r.id) === id)
  return rec ? { status: 200, body: ok([rec]) } : NOT_FOUND(what, id)
}

function createOf(
  args: OperationArgs,
  required: string[],
  allowed: string[],
  idPrefix: string,
  store: (ws: Workspace) => Record<string, unknown>[],
): OperationResult {
  const body = args.body || {}
  const missing = required.filter((k) => body[k] === undefined || body[k] === '')
  if (missing.length > 0) {
    return { status: 400, body: blocked(`required members missing: ${missing.join(', ')} — the door is fine, the request body is incomplete`) }
  }
  const { ws, minted } = workspaceOf(args.request, true)
  if (minted) {
    const { identityClass, referral } = identityClassOf(args.request)
    emitSeam({ seam: 'signup', identityClass, referral, workspace: ws!.id })
  }
  const picked = Object.fromEntries(Object.entries(body).filter(([k]) => allowed.includes(k)))
  const record = {
    id: `${idPrefix}_${crypto.randomUUID().slice(0, 8)}`,
    example: true as const,
    label: `sandbox-minted example record — ${RETENTION_NOTE}`,
    workspace: ws!.id,
    ...picked,
  }
  store(ws!).push(record)
  return { status: 201, body: ok([record], { extra: { workspace: ws!.id, retention: RETENTION_NOTE } }) }
}

export function executeOperation(op: OperationDef, args: OperationArgs): OperationResult {
  const wsHeader = args.request.headers.get('x-workspace')
  const ws = wsHeader ? workspaces.get(wsHeader) : undefined
  switch (op.id) {
    case 'listPlacements': {
      // workspace-merged view; the keyless (no-workspace) path is served by the
      // generator from the SAME manifest rows — one definition, one collection
      const merged = { ...manifest, collection: { ...manifest.collection, records: [...manifest.collection.records, ...(ws?.placements || [])] } }
      const params = new URLSearchParams(Object.entries(args.filters || {}))
      const d = collectionDecision(merged, params)
      return { status: d.status, body: d.body }
    }
    case 'getPlacement': return getOf(seedPlacements as unknown as Record<string, unknown>[], ws?.placements, args.id!, 'placement')
    case 'createPlacement': return createOf(args, ['candidateId', 'jobOrderId', 'onetCode'], ['candidateId', 'jobOrderId', 'onetCode', 'startDate', 'feeModel'], 'plc_ws', (w) => w.placements)
    case 'listCandidates': return listOf(seedCandidates as unknown as Record<string, unknown>[], ws?.candidates, args.filters, 'candidates')
    case 'getCandidate': return getOf(seedCandidates as unknown as Record<string, unknown>[], ws?.candidates, args.id!, 'candidate')
    case 'createCandidate': return createOf(args, ['name', 'onetCode'], ['name', 'onetCode', 'skills', 'metro'], 'cand_ws', (w) => w.candidates)
    case 'listJobOrders': return listOf(seedJobOrders as unknown as Record<string, unknown>[], ws?.jobOrders, args.filters, 'jobOrders')
    case 'getJobOrder': return getOf(seedJobOrders as unknown as Record<string, unknown>[], ws?.jobOrders, args.id!, 'jobOrder')
    case 'createJobOrder': return createOf(args, ['client', 'title', 'onetCode'], ['client', 'title', 'onetCode', 'billRateUsdHour'], 'job_ws', (w) => w.jobOrders)
    case 'listOccupations': return { status: 200, body: ok(occupations, { memberName: 'occupations' }) }
    case 'getOccupation': return getOf(occupations as unknown as Record<string, unknown>[], undefined, args.id!, 'occupation')
    default: return { status: 404, body: { type: 'EMPTY', results: [], message: `operation ${op.id} is not served` } }
  }
}

const opById = new Map(staffingTalent.operations.map((op) => [op.id, op]))

