// ─── MCP (JSON-RPC 2.0 — tools/list + tools/call over the one registry) ─────

async function mcpResponse(request: Request): Promise<Response> {
  let rpc: { jsonrpc?: string; id?: unknown; method?: string; params?: { name?: string; arguments?: Record<string, unknown> } }
  try {
    rpc = await request.json()
  } catch {
    return Response.json({ jsonrpc: '2.0', id: null, error: { code: -32700, message: 'parse error — body must be JSON-RPC 2.0' } }, { status: 400 })
  }
  const reply = (result: unknown) => Response.json({ jsonrpc: '2.0', id: rpc.id ?? null, result })
  const error = (code: number, message: string, status = 400) =>
    Response.json({ jsonrpc: '2.0', id: rpc.id ?? null, error: { code, message } }, { status })

  switch (rpc.method) {
    case 'initialize':
      return reply({ protocolVersion: '2025-06-18', serverInfo: { name: 'api.careers', version: manifest.version }, capabilities: { tools: {} } })
    case 'tools/list':
      return reply({
        tools: staffingTalent.operations.map((op) => ({
          name: op.id,
          description: op.summary,
          inputSchema: {
            type: 'object',
            properties: {
              ...(op.verb === 'get' && { id: { type: 'string' } }),
              ...(op.verb === 'list' && { status: { type: 'string' }, occupation: { type: 'string' } }),
              ...(op.verb === 'create' && { record: { type: 'object' } }),
            },
            ...(op.verb === 'get' && { required: ['id'] }),
          },
        })),
      })
    case 'tools/call': {
      const name = rpc.params?.name
      const op = name ? opById.get(name) : undefined
      if (!op) return error(-32602, `unknown tool ${JSON.stringify(name)} — tools/list names the served set`)
      const a = rpc.params?.arguments || {}
      const result = executeOperation(op, {
        id: typeof a.id === 'string' ? a.id : undefined,
        filters: Object.fromEntries(Object.entries(a).filter(([k, v]) => (k === 'status' || k === 'occupation') && typeof v === 'string')) as Record<string, string>,
        body: (a.record as Record<string, unknown>) || (a as Record<string, unknown>),
        request,
      })
      emitSeam({ seam: 'meter', operation: op.id, transport: 'mcp' })
      return reply({ content: [{ type: 'text', text: JSON.stringify(result.body) }], isError: result.status >= 400 })
    }
    default:
      return error(-32601, `method ${JSON.stringify(rpc.method)} is not served — this door answers initialize, tools/list, tools/call`)
  }
}

// ─── the fetch pipeline ──────────────────────────────────────────────────────

const axp = createAxpRoutes(manifest)

const JSON_CT = { 'content-type': 'application/json; charset=utf-8' }

/** One REST door: scope law, body parse, registry dispatch, meter seam. */
async function serveOperation(op: OperationDef, request: Request, url: URL): Promise<Response> {
  // reserved scopes answer BLOCKED on every collection, not only the branching one
  const scope = url.searchParams.get('scope')
  if (scope !== null && ['admin', 'internal'].includes(scope)) {
    return envelopeResponse(blocked(`scope '${scope}' is reserved to the platform — not permitted for your agent class`))
  }
  const id = op.verb === 'get' ? url.pathname.split('/').pop() : undefined
  let body: Record<string, unknown> | undefined
  if (request.method === 'POST') {
    try {
      body = await request.json()
    } catch {
      return envelopeResponse(blocked('the request body must be JSON'), { status: 400 })
    }
  }
  const result = executeOperation(op, { id, filters: Object.fromEntries(url.searchParams), body, request })
  emitSeam({ seam: 'meter', operation: op.id })
  return new Response(JSON.stringify(result.body), { status: result.status, headers: JSON_CT })
}

function meterFor(path: string, method: string): string | undefined {
  if (method === 'GET') {
    if (path === '/placements') return 'listPlacements'
    if (/^\/placements\/[^/]+$/.test(path)) return 'getPlacement'
    if (path === '/candidates') return 'listCandidates'
    if (/^\/candidates\/[^/]+$/.test(path)) return 'getCandidate'
    if (path === '/job-orders') return 'listJobOrders'
    if (/^\/job-orders\/[^/]+$/.test(path)) return 'getJobOrder'
    if (path === '/occupations') return 'listOccupations'
    if (/^\/occupations\/[^/]+$/.test(path)) return 'getOccupation'
  }
  if (method === 'POST') {
    if (path === '/placements') return 'createPlacement'
    if (path === '/candidates') return 'createCandidate'
    if (path === '/job-orders') return 'createJobOrder'
  }
  return undefined
}

export default {
  async fetch(request: Request): Promise<Response> {
    const url = new URL(request.url)
    const path = url.pathname
    const method = request.method

    // MCP door (declared on the card — presence-when-true, and it answers)
    if (path === '/mcp' && method === 'POST') return mcpResponse(request)

    // headless-ply POST doors — BEFORE the generator, which owns the
    // collection path for GET/HEAD and would answer 405 to a POST it never
    // serves (the POST door is ours, on the same collection — one definition)
    if (method === 'POST') {
      const operation = meterFor(path, 'POST')
      if (operation) return serveOperation(opById.get(operation)!, request, url)
    }

    // workspace-merged collection read (same manifest rows; the keyless path
    // stays with the generator so probe behavior is the generator's, verbatim)
    if (path === '/placements' && method === 'GET' && request.headers.get('x-workspace')) {
      const op = opById.get('listPlacements')!
      const result = executeOperation(op, { filters: Object.fromEntries(url.searchParams), request })
      emitSeam({ seam: 'meter', operation: op.id })
      return new Response(JSON.stringify(result.body), { status: result.status, headers: JSON_CT })
    }

    // the generated quartet + collection + offer + family + home
    const hit = await axp(request)
    if (hit !== undefined) {
      const metered = meterFor(path, method)
      if (metered) emitSeam({ seam: 'meter', operation: metered })
      if (path === manifest.pricing.offerPath || hit.status === 402) {
        // §7.4 money-event seam — a labeled stub: an offer boundary was served;
        // no settlement occurs on this deployment
        emitSeam({ seam: 'money-event', kind: 'offer-served', stub: true, operation: metered })
      }
      if (path === '/') {
        const { identityClass, referral } = identityClassOf(request)
        emitSeam({ seam: 'traffic', identityClass, referral })
      }
      return hit
    }

    // machine-face extras
    if (path === '/icp.json' && (method === 'GET' || method === 'HEAD')) {
      return new Response(method === 'HEAD' ? null : JSON.stringify(icpDocument, null, 2), { status: 200, headers: JSON_CT })
    }
    if (path === '/verify' && (method === 'GET' || method === 'HEAD')) {
      return new Response(method === 'HEAD' ? null : JSON.stringify(verifyDocument, null, 2), { status: 200, headers: JSON_CT })
    }

    // the two plies — remaining REST doors over the one operation registry
    const operation = meterFor(path, method)
    if (operation) return serveOperation(opById.get(operation)!, request, url)

    return envelopeResponse(
      { type: 'EMPTY', results: [], message: `no route at ${path} — nothing here has been deleted; the route was never written. The card at ${ORIGIN}/.well-known/agents.json names every door.` },
      { status: 404 },
    )
  },
}
